import React, { useEffect, useMemo, useRef, useState } from 'react';
import { api, auth } from '@appdeploy/client';
import { ArrowRight, Bell, CalendarDays, Check, ChevronLeft, CloudRain, Compass, Copy, Download, Heart, Home, LocateFixed, LogIn, Map, MapPin, Mic, Palette, Play, Plus, Search, Send, Share2, Sparkles, Trash2, User, Users, Wallet, X } from 'lucide-react';
