    {screen === 'home' && <HomeScreen search={search} setSearch={setSearch} category={category} setCategory={setCategory} states={filteredStates} openState={openState} openPlace={openPlace} saved={saved} toggleSave={toggleSave} onVlog={() => setVideoOpen(true)} onTravelAssist={openTravelAssist} />}
