    {screen === 'admin' && (isAdmin ? <AdminScreen bookings={adminBookings} onReview={reviewBooking} onLogout={adminLogout} /> : <div className='content profile-page'><div className='empty-row'>Admin login required.</div></div>)}
    {adminLoginOpen && <AdminLoginModal onClose={() => setAdminLoginOpen(false)} onSubmit={adminLogin} />}
