const getLiveTransportSearch = (from: string, to: string, mode: 'train' | 'bus' | 'flight', date: string) => { const fromSlug = encodeURIComponent(from.trim().toLowerCase().replace(/\s+/g, '-')); const toSlug = encodeURIComponent(to.trim().toLowerCase().replace(/\s+/g, '-')); const routeText = encodeURIComponent(`Flights from ${from} to ${to}${date ? ` on ${date}` : ''}`); if (mode === 'train') return [{ name: 'ixigo · trains between stations', url: `https://www.ixigo.com/by-train-rail/${fromSlug}-to-${toSlug}-by-train`, note: 'Current train names, schedules, classes and booking options' }, { name: 'Indian Railways · official search', url: 'https://www.indianrail.gov.in/enquiry/SEAT/SeatAvailability.html?locale=en', note: 'Official railway availability/verification' }]; if (mode === 'bus') return [{ name: 'redBus · live route search', url: `https://www.redbus.in/bus-tickets/${fromSlug}-to-${toSlug}`, note: 'Current operators, boarding points, fares and seats' }, { name: 'MakeMyTrip · bus route search', url: `https://www.makemytrip.com/bus-tickets/${fromSlug}-${toSlug}_bus-ticket-booking.html`, note: 'Alternative bus inventory and boarding points' }]; return [{ name: 'Google Flights · route search', url: `https://www.google.com/travel/flights?q=${routeText}`, note: 'Current direct and connecting flight options for the selected route/date' }, { name: 'FlightConnections · route map', url: `https://www.flightconnections.com/flights-from-${fromSlug}-to-${toSlug}`, note: 'Airline route and connection overview' }]; };
const getAlternateLocations = (data: RecommendationData, mode: 'train' | 'bus' | 'flight') => { if (!data.origin || !data.destination) return []; const originItems = mode === 'train' ? data.origin.railStations : mode === 'bus' ? data.origin.busStops : data.origin.airports; const destinationItems = mode === 'train' ? data.destination.railStations : mode === 'bus' ? data.destination.busStops : data.destination.airports; return [...originItems.slice(0, 3).map((item) => ({ ...item, side: 'Origin' })), ...destinationItems.slice(0, 3).map((item) => ({ ...item, side: 'Destination' }))]; };
